import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPubSub;

public class RedisPubSubExample {
    public static void main(String[] args) throws InterruptedException {
        Jedis jedisPublisher = new Jedis("localhost", 6379);
        Jedis jedisSubscriber = new Jedis("localhost", 6379);

        JedisPubSub subscriber = new JedisPubSub() {
            @Override
            public void onMessage(String channel, String message) {
                System.out.println("Received message: " + message + " from channel: " + channel);
            }
        };

        // Subscribing is a blocking operation, run in a separate thread
        new Thread(() -> {
            jedisSubscriber.subscribe(subscriber, "notifications");
        }).start();

        Thread.sleep(500); // Wait for subscription to establish

        jedisPublisher.publish("notifications", "Hello, Redis Pub/Sub!");

        Thread.sleep(1000);
        subscriber.unsubscribe();
        jedisPublisher.close();
        jedisSubscriber.close();
    }
}
